    global last
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    if not cam:
        return (1.7*h,-0.5,-41)
    sides=[[],[]]
    th=math.radians(obs['rig']['trailer_heading_deg'])
    for b,d in cam.get('walls',[]):
        a=math.radians(b)-th
        u=-d*math.cos(a); y=d*math.sin(a)
        if 0.8<u<14.5 and abs(y)>1:
            sides[0 if y<0 else 1].append((u,y))
    vals=[]
    for pts in sides:
        if len(pts)>=2:
            n=len(pts); sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
            den=sum(p[0]**2 for p in pts)-sx*sx/n
            m=(sum(x*y for x,y in pts)-sx*sy/n)/max(den,0.1)
            vals.append(sy/n+m*(9-sx/n))
    if len(vals)==2:
        y=sum(vals)/2
        desired=math.degrees(math.atan(2*10.2*y/81))
        desired=max(-38,min(38,desired))
        last=0.9*last+0.1*desired
    steer=max(-42,min(42,1.8*h-1.4*last))
    if abs(h)>55:
        wake('Large hitch angle')
        return (steer,0,-41)
